@Composable
fun BrandLogo(brand: String, size: Dp = Tokens.Size.IconSm) {
    val path = remember(brand) { PathParser().parsePathString(BrandPaths.getValue(brand)).toPath().apply { fillType = PathFillType.EvenOdd } }
    val tint = MyTheme.colors.text

    Canvas(Modifier.size(size)) {
        val scale = this.size.width / LogoViewBox

        withTransform({ scale(scale, scale, pivot = Offset.Zero) }) {
            drawPath(path, tint)
        }
    }
}
